{
  "status": "SUPPORTED",
  "task_summary": "Prepare living room for two people by providing refreshment settings and placing entertainment control.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "person",
        "entity_kind": "OBJECT",
        "function": "Recipient of refreshments and control access",
        "required_count": 2,
        "binding_policy": "DISTINCT"
      ,
      "candidate_categories": ["human", "guest", "viewer"],
      "required_properties": ["capable_of_sitting", "capable_of_viewing"]
      },
      {
        "id": "refreshment_setting",
        "entity_kind": "OBJECT",
        "function": "Vessel for refreshment placed near person",
        "required_count": 2,
        "binding_policy": "DISTINCT"
      ,
      "candidate_categories": ["cup", "glass", "mug", "bowl"],
      "required_properties": ["holds_liquid", "portable"]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "Device to operate television",
        "required_count": 1,
        "binding_policy": "REUSABLE"
      ,
      "candidate_categories": ["remote", "controller", "handheld_device"],
      "required_properties": ["wireless", "operates_tv"]
      }
    ],
    "functional_relations": [
      {
        "id": "refreshment_proximity",
        "relation": "refreshment_setting is nearby person",
        "participant_roles": [
          "refreshment_setting",
          "person"
        ]
      ,
        "required": true
      },
      {
        "id": "control_accessibility",
        "relation": "entertainment_control is accessible to both people",
        "participant_roles": [
          "entertainment_control",
          "person"
        ]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "provide_refreshments",
        "operation": "Place refreshment_setting near person",
        "participant_roles": [
          "refreshment_setting",
          "person"
        ]
      ,
        "operation_count": 2
      },
      {
        "id": "position_control",
        "operation": "Place entertainment_control in accessible location",
        "participant_roles": [
          "entertainment_control"
        ,
          "person"
        ]
      ,
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "person": []
    ,
      "refreshment_setting": [
        {
          "label": "cups on desk",
          "visual_description": "Two red cups on the large desk in foreground"
        }
      ],
      "entertainment_control": [
        {
          "label": "remote on desk",
          "visual_description": "Black remote control on the large desk in foreground"
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "desk",
        "label": "Large desk in foreground",
        "visual_description": "Wooden table with drawers and items on top",
        "reason": "Contains remote and cups; drawers may hold additional items"
      },
      {
        "id": "side_tables",
        "label": "Side tables next to chairs",
        "visual_description": "Small tables flanking the armchairs",
        "reason": "Shelves could be searched for spare cups or settings"
      }
    ],
    "inspection_order": [
      "desk",
      "side_tables"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
